    // Number of commit ports. Forced to 2 if SuperscalarEn.
    int unsigned NrCommitPorts;
    // Load cycle latency number
    int unsigned NrLoadPipeRegs;
    // Store cycle latency number
    int unsigned NrStorePipeRegs;
    // Scoreboard length
